import{_ as e,o as t,c as a,ag as _}from"./chunks/framework.Ddwm6YJC.js";const m=JSON.parse('{"title":"第三卷 潮汐 · 第70章 和好如初","description":"","frontmatter":{},"headers":[],"relativePath":"第70章_和好如初.md","filePath":"第70章_和好如初.md"}'),o={name:"第70章_和好如初.md"};function r(n,p,s,c,i,l){return t(),a("div",null,[...p[0]||(p[0]=[_('<h1 id="第三卷-潮汐-·-第70章-和好如初" tabindex="-1">第三卷 潮汐 · 第70章 和好如初 <a class="header-anchor" href="#第三卷-潮汐-·-第70章-和好如初" aria-label="Permalink to &quot;第三卷 潮汐 · 第70章 和好如初&quot;">​</a></h1><blockquote><p>【小注：本章为江苒视角】河边长椅上的那几条约定，她一条一条都记得。接第69章。</p></blockquote><p>我到河边时，沈聿已经在长椅上了。他坐得很端正，书包放在脚边，外套袖子拉到手背上，风把他刚在堤上沾的潮气吹干，长椅的木纹被风吹得发凉。看见我，他立刻站起来，手在裤缝上蹭了两下，又不知该坐还是该站，眼神亮亮的，像等了很久。</p><p>我把手里的纸袋抱紧，指尖被袋子的热气焐得有点出汗。风从河面吹来，带着潮湿的腥气和落叶的凉，我把围巾拉高，闻到围巾里淡淡的皂香。</p><p>我把纸袋递过去，里面是宋阿婆蒸的红薯，还烫手。</p><p>“坐吧，站着多冷。”我说。</p><p>他笑着坐下，特意让出很大一块地方。长椅冰凉，隔着衣料透进来。河水在雾里慢慢走，落叶贴在水面打转，远处有船声，闷闷的，看不清影子。</p><p>他袖口露出半张揉皱的纸，我知道那颗星星里的话他看过了。纸角被他攥得有点潮，边上起了毛。他冲我笑了一下，把纸按回去，什么也不说，眼角弯弯的。我把红薯往他那边推了推，袋子发出轻响，热气一股股往上冒。</p><p>我想起昨晚在台灯下拆开那颗星星时，手抖得差点撕破纸，如今看他袖口的纸，心里像被热水轻轻烫了一下。\\n\\n我们有好些日子没这样坐了。自从在教室外吵完那一架，谁也没先开口。陈默在中间传过两次话，话里话外都是别犟，林小满塞给我一颗海盐糖，说甜的东西能让人心软，还把糖纸在我掌心捻了捻，说含着别急着咬。我含着那颗糖，先尝到咸，随后才是甜，糖在舌尖慢慢化开，心里却还是酸的，像被风吹皱的水面。</p><p>“好吃吗。”我问。</p><p>“烫。”他捧着红薯小口咬着，“你吃了吗。”</p><p>“吃了。”</p><p>话断在这里。风把梧桐叶吹到椅脚，沙沙响。我低头看鞋尖，双结的鞋带是早上顾远帮我系的，他说这样才不会散。</p><p>“我那天语气太冲了。”沈聿忽然说。</p><p>我抬头看他，他耳尖发红，眼睛看着河面。</p><p>“哪天。”我故意问。</p><p>“走廊那天。”他急着转头，“我说你总把事藏在心里，还说你这样让人很累。说完我就后悔了。”</p><p>我想起那天的亮光，刺得人睁不开眼。我转身就走，眼泪掉在楼梯拐角，何晓老师在身后喊了我一声，我没停。</p><p>“你说的也没错，我确实什么都藏着。”我说。</p><p>“可我不该那样说。”他声音低下去，“你藏着，是怕麻烦别人。叶老师说过，你从小就先替别人想。”</p><p>我鼻子一酸，把头扭向河面。雾湿湿的，落在睫毛上，凉凉的。</p><p>“江苒，我们和好吗，像以前那样。”他认真喊我的名字。</p><p>我没回答，从口袋摸出一颗纸星星。边角起了毛，是当初一起折的那批。我摊开手心给他看。</p><p>“记得吗。”</p><p>他点头，从书包侧袋掏出小玻璃罐，里面装满纸星星，晃起来哗啦响。</p><p>“我一直带着，吵完那晚数了一遍，少了一颗，原来在你这里。”</p><p>我把星星放进去，正好填满空缺。他把罐子抱在怀里，像抱着宝贝。</p><p>“我去问了宋阿婆，她说星星要两个人一起折才灵，一个人折的，容易散。她还说，冷战的时候就去河边坐坐，雾会把气话打湿，剩下的话就是真心话。”</p><p>我忍不住笑了，笑着笑着掉下一颗泪，砸在手背上。</p><p>他伸手想替我擦，又停在半空。我用袖子擦掉，说没事，是风吹的。</p><p>他剥开一颗海盐糖递给我，糖纸在他指尖发出细细的脆响。我含住，咸甜在舌尖化开，先咸后甜，暖意顺着喉咙下去。这味道很熟，林小满给我的那颗也是这个味道，原来我们都在用同一颗糖哄自己。我把糖在嘴里含得更慢一点，听见河水拍岸的轻响。</p><p>“还有磁带。”他掏出那盘旧磁带，标签已经褪色，纸面被指腹摩得起毛，“顾远帮我修好了，他说这种老东西，要用细笔一点点卷，急不得，要等它自己卡住再推一下。”他把磁带托在掌心，齿轮轻轻转了一下，发出很轻的咔声。</p><p>我接过来看了看，塑料壳凉凉的，有他手心的温度残留。</p><p>“就像我们吗。”我说。</p><p>他重重点头：“对，就像我们。”</p><p>河雾薄了一点，露出一点水光，像一块被风擦亮的玻璃。我把红薯掰了一半给他，外皮有点烫，手被热气熏得发红，他掰了一半给我，红薯心软软的，甜香混着热气扑在脸上，眼睛都湿润了。</p><p>“把那个约定再说一遍吧。”我说。</p><p>他坐直，把磁带和星星罐放在长椅中间，像某种仪式。</p><p>“二十七的约定，当初折了二十七颗星星，说好不管吵多少次，都要坐下来，把话说完。”</p><p>“第一句是什么。”</p><p>“不许走开，吵架也要坐在同一张长椅上。”</p><p>“第二句呢。”</p><p>“不许留到明天，今天的事在雾散之前说完。”我说。</p><p>“第三句，如果有人先低头，另一个人要递糖。”他声音有点抖，“我刚才递了，你也吃了，算和好了吗。”</p><p>“还差一句。”他又说。</p><p>“哪句。”</p><p>他深吸一口气，头发被风吹乱，伸出手掌，停在我面前：“以后的路还一起走，去雾山外面看看，再回来，把星星罐装满，把磁带听完。”</p><p>我把手放进他的掌心，他的手很暖，带着红薯的热气，微微出汗。</p><p>“好，再说一遍，我记住了。”我说。</p><p>“要拉钩吗，像小时候那样。”他问。</p><p>“要。”</p><p>我们拉钩盖章，手指勾在一起，凉凉的又很快焐热，幼稚的动作在雾里显得郑重。指腹相贴，有点汗，轻轻一拉又扣紧。赵晴看见肯定会笑，陈默一定会说，这才是我们，何晓会点头说，总算回来了。</p><p>桥上传来脚步声，林小满和陈默站在那里挥手，没走近。林小满举着新买的糖，陈默双手拢在嘴边，无声地笑着。</p><p>“他们一直在等我们和好。”我说。</p><p>“顾远说，长椅空了好几天，河都觉得冷清了。”他说。</p><p>我靠着椅背，肩膀轻轻碰到他的肩膀，谁也没移开。雾落在外套上，结成细小水珠，凉凉软软的。</p><p>他把磁带放进随身听，分给我一只耳机。沙沙的电流声后，是那首听过很多遍的歌，声音有点失真，却很暖，像从远处游过来。星星罐放在中间，随着轻晃发出细碎的响。</p><p>我把星星罐晃了晃，声音细碎，像一罐小小的潮汐。热水在纸杯里凉了一半，我捧着喝了一口，温温的，不烫。</p><p>“以后吵架，还来这里好吗。”他问。声音混着河风，轻轻的。</p><p>“好，就来这张长椅。”我说。</p><p>雾渐渐散了，水鸟掠过，翅膀声很轻，阳光落在椅面上，一点点变暖。红薯吃完了，糖也化完了，歌还在继续。我握着那只温热的耳机，听着他的呼吸落在歌声上面，心里那块沉沉的石头，像被河水泡软了一角。我想，和好如初的意思，大概就是裂缝还在，光却透进来了。</p><p>就在这时，随身听轻轻卡了一下，歌声顿了顿，磁带转得慢了一拍，随后又顺起来。我们对视一眼，都没说话。</p><p>我把耳机往他那边推了推，歌声重新漫上来，混着河面吹来的风声，很暖。我低声说，这盘带子以后少听笑场，多听海浪吧。他点头，说好，留着以后慢慢听。热气和歌声绕在一起，心里的石头又软了一角。</p>',63)])])}const f=e(o,[["render",r]]);export{m as __pageData,f as default};
